parameters.jsCode:
const originalItems = $('get').all().map(({ json }) => json);

const byIdentifier = new Map(
  originalItems.map((item) => [String(item.identifier), item]),
);

const byId = new Map(
  originalItems.map((item) => [String(item.id), item]),
);

const classifications = $input.all().flatMap(({ json }) => {
  if (!Array.isArray(json.output)) {
    throw new Error('Un item del LLM no contiene output como arreglo');
  }

  return json.output;
});

const classifiedAt = new Date().toISOString();

const batch = classifications.map((item) => {
  const key = String(item.id);

  const og = byIdentifier.get(key) ?? byId.get(key);

  if (!og) {
    throw new Error(`No se encontró publicación original para id: ${key}`);
  }

  return {
    ...og,
    ...item,
    id: og.id,
    identifier: og.identifier,
    llm_model: 'gpt-5.6-terra',
    llm_prompt_version: '4',
    llm_classified_at: classifiedAt,
  };
});

return [{ json: { batch } }];

const posts = $input.all().map(({ json }) => ({
  identifier: String(json.identifier),
  text: json.text,
}));

return [{ json: { posts } }];
